BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @OccurredAtUtc datetime2(3) =
        SYSUTCDATETIME();

    DECLARE @ResolvedCorrelationId uniqueidentifier =
        COALESCE(@CorrelationId, NEWID());

    DECLARE @NormalizedEmailAddress nvarchar(254);

    SET @NormalizedEmailAddress =
        NULLIF(
            LTRIM(RTRIM(@EmailAddress)),
            N''
        );

    IF @NormalizedEmailAddress IS NULL
    BEGIN
        THROW 51020,
            N'EmailAddress is required.',
            1;
    END;

    IF @NormalizedEmailAddress LIKE N'% %'
    BEGIN
        THROW 51021,
            N'EmailAddress cannot contain spaces.',
            1;
    END;

    IF @PasswordHash IS NULL
       OR LEN(LTRIM(RTRIM(@PasswordHash))) = 0
    BEGIN
        THROW 51022,
            N'PasswordHash is required.',
            1;
    END;

    IF @TemporaryPasswordExpiresAtUtc <= @OccurredAtUtc
    BEGIN
        THROW 51023,
            N'TemporaryPasswordExpiresAtUtc must be in the future.',
            1;
    END;

    DECLARE @RoleId int;
    DECLARE @UserId int;

    BEGIN TRY
        BEGIN TRANSACTION;

        /*
            The locking hints prevent two bootstrap processes
            from creating initial administrators simultaneously.
        */

        IF EXISTS
        (
            SELECT 1
            FROM [Security].[Users]
                WITH (UPDLOCK, HOLDLOCK)
        )
        BEGIN
            THROW 51024,
                N'The initial administrator can only be created when no users exist.',
                1;
        END;

        SELECT
            @RoleId = R.[RoleId]
        FROM [Security].[Roles] AS R
            WITH (UPDLOCK, HOLDLOCK)
        WHERE R.[RoleCode] = N'SuperAdministrator'
          AND R.[IsActive] = 1;

        IF @RoleId IS NULL
        BEGIN
            THROW 51025,
                N'The active SuperAdministrator role was not found.',
                1;
        END;

        INSERT INTO [Security].[Users]
        (
            [RoleId],
            [EmailAddress],
            [PasswordHash],
            [IsEmailConfirmed],
            [IsActive],
            [RequiresPasswordChange],
            [TemporaryPasswordExpiresAtUtc],
            [PasswordChangedAtUtc],
            [FailedLoginAttempts],
            [LockoutEndAtUtc],
            [LastLoginAtUtc],
            [CreatedByUserId]
        )
        VALUES
        (
            @RoleId,
            @NormalizedEmailAddress,
            @PasswordHash,
            1,
            1,
            1,
            @TemporaryPasswordExpiresAtUtc,
            NULL,
            0,
            NULL,
            NULL,
            NULL
        );

        SET @UserId =
            CONVERT(int, SCOPE_IDENTITY());

        INSERT INTO [Audit].[AuditLogs]
        (
            [CorrelationId],
            [ModuleName],
            [ActionName],
            [EntityName],
            [EntityId],
            [ActorType],
            [ActorEmailAddress],
            [ActorRoleCode],
            [IsSuccessful],
            [EventDescription],
            [ClientIpAddress],
            [UserAgent],
            [HttpMethod],
            [RequestPath],
            [OccurredAtUtc]
        )
        VALUES
        (
            @ResolvedCorrelationId,
            N'Security',
            N'InitialSuperAdministratorCreated',
            N'Users',
            CONVERT(nvarchar(100), @UserId),
            N'System',
            @NormalizedEmailAddress,
            N'SuperAdministrator',
            1,
            N'Initial SuperAdministrator account created.',
            @ClientIpAddress,
            @UserAgent,
            N'POST',
            @RequestPath,
            @OccurredAtUtc
        );

        COMMIT TRANSACTION;

        SELECT
            U.[UserId],
            U.[EmailAddress],
            R.[RoleCode],
            U.[IsActive],
            U.[RequiresPasswordChange],
            U.[TemporaryPasswordExpiresAtUtc],
            U.[CreatedAtUtc]
        FROM [Security].[Users] AS U

        INNER JOIN [Security].[Roles] AS R
            ON R.[RoleId] = U.[RoleId]

        WHERE U.[UserId] = @UserId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        THROW;
    END CATCH;
END;

CREATE PROCEDURE [Security].[CreateInitialSuperAdministrator]
    @EmailAddress nvarchar(254),
    @PasswordHash nvarchar(500),
    @TemporaryPasswordExpiresAtUtc datetime2(3),
    @CorrelationId uniqueidentifier = NULL,
    @ClientIpAddress nvarchar(45) = NULL,
    @UserAgent nvarchar(512) = NULL,
    @RequestPath nvarchar(500) = NULL
AS

BEGIN SET NOCOUNT ON;
DECLARE @NormalizedEmailAddress nvarchar(254);
SET @NormalizedEmailAddress = LTRIM(RTRIM(@EmailAddress));
IF @NormalizedEmailAddress IS NULL OR @NormalizedEmailAddress = N'' BEGIN RETURN; END;
SELECT U.[UserId], U.[EmailAddress], U.[PasswordHash], U.[IsEmailConfirmed], U.[IsActive], U.[RequiresPasswordChange], U.[TemporaryPasswordExpiresAtUtc], U.[PasswordChangedAtUtc], U.[FailedLoginAttempts], U.[LockoutEndAtUtc], U.[LastLoginAtUtc],
R.[RoleId], R.[RoleCode], R.[DisplayName] AS [RoleDisplayName], R.[IsActive] AS [IsRoleActive],
E.[EmployeeId], E.[FirstName], E.[LastName], E.[JobTitle], E.[ProfileImagePath], E.[IsActive] AS [IsEmployeeActive],
D.[DepartmentId], D.[DepartmentCode], D.[Name] AS [DepartmentName]
FROM [Security].[Users] AS U
INNER JOIN [Security].[Roles] AS R ON R.[RoleId] = U.[RoleId]
LEFT JOIN [HumanResources].[Employees] AS E ON E.[UserId] = U.[UserId]
LEFT JOIN [HumanResources].[Departments] AS D ON D.[DepartmentId] = E.[DepartmentId]
WHERE U.[EmailAddress] = @NormalizedEmailAddress; END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @MaximumFailedAttempts < 1
       OR @MaximumFailedAttempts > 20
    BEGIN
        THROW 51010,
            N'MaximumFailedAttempts must be between 1 and 20.',
            1;
    END;

    IF @LockoutDurationMinutes < 1
       OR @LockoutDurationMinutes > 1440
    BEGIN
        THROW 51011,
            N'LockoutDurationMinutes must be between 1 and 1440.',
            1;
    END;

    DECLARE @OccurredAtUtc datetime2(3) =
        SYSUTCDATETIME();

    DECLARE @ResolvedCorrelationId uniqueidentifier =
        COALESCE(@CorrelationId, NEWID());

    DECLARE @NormalizedEmailAddress nvarchar(254);

    SET @NormalizedEmailAddress =
        NULLIF(
            LTRIM(RTRIM(@AttemptedEmailAddress)),
            N''
        );

    IF @NormalizedEmailAddress IS NULL
    BEGIN
        THROW 51012,
            N'AttemptedEmailAddress is required.',
            1;
    END;

    DECLARE @RoleCode nvarchar(50);

    DECLARE @CurrentFailedLoginAttempts smallint = 0;
    DECLARE @CurrentLockoutEndAtUtc datetime2(3);

    DECLARE @NewFailedLoginAttempts smallint = 0;
    DECLARE @NewLockoutEndAtUtc datetime2(3);

    DECLARE @ShouldUpdateUser bit = 0;

    DECLARE @AdditionalDataJson nvarchar(max);

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @UserId IS NOT NULL
        BEGIN
            SELECT
                @NormalizedEmailAddress = U.[EmailAddress],
                @RoleCode = R.[RoleCode],
                @CurrentFailedLoginAttempts =
                    U.[FailedLoginAttempts],
                @CurrentLockoutEndAtUtc =
                    U.[LockoutEndAtUtc]
            FROM [Security].[Users] AS U
                WITH (UPDLOCK, HOLDLOCK)

            INNER JOIN [Security].[Roles] AS R
                ON R.[RoleId] = U.[RoleId]

            WHERE U.[UserId] = @UserId;

            IF @RoleCode IS NULL
            BEGIN
                THROW 51013,
                    N'The user was not found.',
                    1;
            END;

            /*
                If the account is already locked, the lockout
                time is not extended with every new attempt.
            */

            IF @CurrentLockoutEndAtUtc IS NOT NULL
               AND @CurrentLockoutEndAtUtc > @OccurredAtUtc
            BEGIN
                SET @NewFailedLoginAttempts =
                    @CurrentFailedLoginAttempts;

                SET @NewLockoutEndAtUtc =
                    @CurrentLockoutEndAtUtc;
            END;
            ELSE
            BEGIN
                DECLARE @BaseFailedLoginAttempts int;
                DECLARE @CalculatedFailedLoginAttempts int;

                SET @BaseFailedLoginAttempts =
                    CASE
                        WHEN @CurrentLockoutEndAtUtc IS NOT NULL
                             AND @CurrentLockoutEndAtUtc
                                 <= @OccurredAtUtc
                            THEN 0
                        ELSE @CurrentFailedLoginAttempts
                    END;

                SET @CalculatedFailedLoginAttempts =
                    @BaseFailedLoginAttempts + 1;

                IF @CalculatedFailedLoginAttempts > 32767
                BEGIN
                    SET @CalculatedFailedLoginAttempts = 32767;
                END;

                SET @NewFailedLoginAttempts =
                    CONVERT(
                        smallint,
                        @CalculatedFailedLoginAttempts
                    );

                IF @NewFailedLoginAttempts
                    >= @MaximumFailedAttempts
                BEGIN
                    SET @NewLockoutEndAtUtc =
                        DATEADD(
                            MINUTE,
                            @LockoutDurationMinutes,
                            @OccurredAtUtc
                        );
                END;
                ELSE
                BEGIN
                    SET @NewLockoutEndAtUtc = NULL;
                END;

                SET @ShouldUpdateUser = 1;
            END;

            IF @ShouldUpdateUser = 1
            BEGIN
                UPDATE [Security].[Users]
                SET
                    [FailedLoginAttempts] =
                        @NewFailedLoginAttempts,

                    [LockoutEndAtUtc] =
                        @NewLockoutEndAtUtc

                WHERE [UserId] = @UserId;
            END;
        END;

        SELECT
            @AdditionalDataJson =
            (
                SELECT
                    @NewFailedLoginAttempts
                        AS [FailedLoginAttempts],

                    @NewLockoutEndAtUtc
                        AS [LockoutEndAtUtc]

                FOR JSON PATH,
                WITHOUT_ARRAY_WRAPPER
            );

        INSERT INTO [Audit].[AuditLogs]
        (
            [CorrelationId],
            [ModuleName],
            [ActionName],
            [EntityName],
            [EntityId],
            [ActorType],
            [ActorUserId],
            [ActorEmailAddress],
            [ActorRoleCode],
            [IsSuccessful],
            [EventDescription],
            [ClientIpAddress],
            [UserAgent],
            [HttpMethod],
            [RequestPath],
            [AdditionalDataJson],
            [OccurredAtUtc]
        )
        VALUES
        (
            @ResolvedCorrelationId,
            N'Security',
            N'LoginFailed',
            CASE
                WHEN @UserId IS NULL
                    THEN NULL
                ELSE N'Users'
            END,
            CASE
                WHEN @UserId IS NULL
                    THEN NULL
                ELSE CONVERT(nvarchar(100), @UserId)
            END,
            N'Anonymous',
            @UserId,
            @NormalizedEmailAddress,
            @RoleCode,
            0,
            N'Authentication attempt failed.',
            @ClientIpAddress,
            @UserAgent,
            N'POST',
            @RequestPath,
            @AdditionalDataJson,
            @OccurredAtUtc
        );

        COMMIT TRANSACTION;

        SELECT
            @UserId AS [UserId],

            @NewFailedLoginAttempts
                AS [FailedLoginAttempts],

            @NewLockoutEndAtUtc
                AS [LockoutEndAtUtc],

            CONVERT
            (
                bit,
                CASE
                    WHEN @NewLockoutEndAtUtc IS NOT NULL
                         AND @NewLockoutEndAtUtc
                             > @OccurredAtUtc
                        THEN 1
                    ELSE 0
                END
            ) AS [IsLockedOut];
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        THROW;
    END CATCH;
END;

CREATE PROCEDURE [Security].[RegisterFailedLogin]
    @AttemptedEmailAddress nvarchar(254),
    @UserId int = NULL,
    @MaximumFailedAttempts smallint = 5,
    @LockoutDurationMinutes int = 15,
    @CorrelationId uniqueidentifier = NULL,
    @ClientIpAddress nvarchar(45) = NULL,
    @UserAgent nvarchar(512) = NULL,
    @RequestPath nvarchar(500) = NULL
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @OccurredAtUtc datetime2(3) =
        SYSUTCDATETIME();

    DECLARE @ResolvedCorrelationId uniqueidentifier =
        COALESCE(@CorrelationId, NEWID());

    DECLARE @EmailAddress nvarchar(254);
    DECLARE @RoleCode nvarchar(50);
    DECLARE @IsUserActive bit;
    DECLARE @IsRoleActive bit;
    DECLARE @LockoutEndAtUtc datetime2(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @EmailAddress = U.[EmailAddress],
            @RoleCode = R.[RoleCode],
            @IsUserActive = U.[IsActive],
            @IsRoleActive = R.[IsActive],
            @LockoutEndAtUtc = U.[LockoutEndAtUtc]
        FROM [Security].[Users] AS U
            WITH (UPDLOCK, HOLDLOCK)

        INNER JOIN [Security].[Roles] AS R
            ON R.[RoleId] = U.[RoleId]

        WHERE U.[UserId] = @UserId;

        IF @EmailAddress IS NULL
        BEGIN
            THROW 51001,
                N'The user was not found.',
                1;
        END;

        IF @IsUserActive = 0
        BEGIN
            THROW 51002,
                N'The user account is inactive.',
                1;
        END;

        IF @IsRoleActive = 0
        BEGIN
            THROW 51003,
                N'The assigned role is inactive.',
                1;
        END;

        IF @LockoutEndAtUtc IS NOT NULL
           AND @LockoutEndAtUtc > @OccurredAtUtc
        BEGIN
            THROW 51004,
                N'The user account is currently locked.',
                1;
        END;

        UPDATE [Security].[Users]
        SET
            [FailedLoginAttempts] = 0,
            [LockoutEndAtUtc] = NULL,
            [LastLoginAtUtc] = @OccurredAtUtc
        WHERE [UserId] = @UserId;

        INSERT INTO [Audit].[AuditLogs]
        (
            [CorrelationId],
            [ModuleName],
            [ActionName],
            [EntityName],
            [EntityId],
            [ActorType],
            [ActorUserId],
            [ActorEmailAddress],
            [ActorRoleCode],
            [IsSuccessful],
            [EventDescription],
            [ClientIpAddress],
            [UserAgent],
            [HttpMethod],
            [RequestPath],
            [OccurredAtUtc]
        )
        VALUES
        (
            @ResolvedCorrelationId,
            N'Security',
            N'LoginSucceeded',
            N'Users',
            CONVERT(nvarchar(100), @UserId),
            N'User',
            @UserId,
            @EmailAddress,
            @RoleCode,
            1,
            N'User authenticated successfully.',
            @ClientIpAddress,
            @UserAgent,
            N'POST',
            @RequestPath,
            @OccurredAtUtc
        );

        COMMIT TRANSACTION;

        SELECT
            U.[UserId],
            U.[LastLoginAtUtc],
            U.[FailedLoginAttempts],
            U.[LockoutEndAtUtc]
        FROM [Security].[Users] AS U
        WHERE U.[UserId] = @UserId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        THROW;
    END CATCH;
END;

CREATE PROCEDURE [Security].[RegisterSuccessfulLogin]
    @UserId int,
    @CorrelationId uniqueidentifier = NULL,
    @ClientIpAddress nvarchar(45) = NULL,
    @UserAgent nvarchar(512) = NULL,
    @RequestPath nvarchar(500) = NULL
